  AND t.requester_type=#{requesterType} AND t.requester_id=#{requesterId}

SELECT 

WHERE t.region=#{region} AND t.requester_type=#{requesterType} AND t.requester_id=#{requesterId}
ORDER BY t.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 

WHERE t.region=#{region}
AND t.status=#{status}
